def compute(vars):
    accrued_revenue_2018 = vars["v1"]
    accrued_revenue_2019 = vars["v2"]
    average_accrued_revenue = (accrued_revenue_2018 + accrued_revenue_2019) / 2

    return {
        "value": average_accrued_revenue,
        "trace": {
            "accrued_revenue_2018": accrued_revenue_2018,
            "accrued_revenue_2019": accrued_revenue_2019,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
